mapper.update:
UPDATE
    leaves
SET
    updated_at= #{model.updatedAt},
    updated_by = #{model.updatedBy},
    deleted_at = #{model.deletedAt}
WHERE
    leave_id = #{leaveId}
AND
    deleted_at = false;

mapper.select:
SELECT count(*) FROM leaves l INNER JOIN users u ON l.user_id = u.user_id INNER JOIN users rt ON l.reported_to_id = rt.user_id WHERE l.deleted_at = false
AND ( leave_status LIKE CONCAT('%', #{paginationDto.searchStr}, '%') OR CONCAT(u.first_name, ' ', u.last_name) LIKE CONCAT('%', #{paginationDto.searchStr}, '%') OR leave_type_name LIKE CONCAT('%', #{paginationDto.searchStr}, '%') )
AND to_date >= #{paginationDto.fromDateInLong}
AND to_date <= #{paginationDto.toDateInLong}
AND leave_status = #{paginationDto.leaveStatus}
AND leave_type_name = #{paginationDto.leaveTypeName}

SELECT l.*, CONCAT(u.first_name, ' ', u.last_name) AS full_name, CONCAT(rt.first_name, ' ', rt.last_name) AS reported_to_full_name FROM leaves l INNER JOIN users u ON l.user_id = u.user_id INNER JOIN users rt ON l.reported_to_id = rt.user_id WHERE l.deleted_at = false
AND ( leave_status LIKE CONCAT('%', #{paginationDto.searchStr}, '%') OR CONCAT(u.first_name, ' ', u.last_name) LIKE CONCAT('%', #{paginationDto.searchStr}, '%') OR leave_type_name LIKE CONCAT('%', #{paginationDto.searchStr}, '%') )
AND to_date >= #{paginationDto.fromDateInLong}
AND to_date <= #{paginationDto.toDateInLong}
AND leave_status = #{paginationDto.leaveStatus}
AND leave_type_name = #{paginationDto.leaveTypeName}
ORDER BY
leave_status
created_at
DESC
ASC
LIMIT #{paginationDto.limit} OFFSET #{paginationDto.offset}
